-- Grupo Alimentario Tres Ríos (GATR): a synthetic food manufacturer's operational data, as its source systems export
-- it. Generated by lab/gatr/generator (do not edit by hand: regenerate). Runs once, when the image is built, in a single
-- transaction in the analytics database, into its own schema, gatr. Each table streams out of its gzipped CSV.
-- Column types are what a generic loader infers: typed only when every value parses; anything else stays text.
-- Comments come from GATR's own data dictionary (lab/gatr/docs/data_dictionary.md), as incomplete as it is.

\set ON_ERROR_STOP on

CREATE SCHEMA gatr;
SET search_path TO gatr;
COMMENT ON SCHEMA gatr IS 'Grupo Alimentario Tres Ríos: operational data exported from its ERP, MES, LIMS, CMMS, WMS, CRM, time clock, IoT and energy systems, and from Planta Delta''s legacy system.';

CREATE TABLE plants (
  plant_id text,
  plant_name text,
  city text,
  province text,
  opened_on date,
  erp_go_live date,
  acquired_on date,
  status text,
  PRIMARY KEY (plant_id)
);
COPY plants FROM PROGRAM 'gzip -dc /seed/gatr/plants.csv.gz' (FORMAT csv, HEADER true);
COMMENT ON TABLE plants IS 'GATR''s manufacturing plants.';
COMMENT ON COLUMN plants.plant_id IS 'Plant code: P1 (Planta Norte), P2 (Planta Sur).';
COMMENT ON COLUMN plants.plant_name IS 'Plant name.';
COMMENT ON COLUMN plants.city IS 'City.';
COMMENT ON COLUMN plants.province IS 'Province.';
COMMENT ON COLUMN plants.opened_on IS 'Date the plant started operating.';
COMMENT ON COLUMN plants.erp_go_live IS 'Date the plant started using the ERP.';
COMMENT ON COLUMN plants.status IS 'ACTIVA / INACTIVA.';

