COMMENT ON TABLE production_lines IS 'Production lines per plant.';
COMMENT ON COLUMN production_lines.line_id IS 'Line code (L1-01 ... at Planta Norte, SUR-01 ... at Planta Sur).';
COMMENT ON COLUMN production_lines.plant_id IS 'Plant.';
COMMENT ON COLUMN production_lines.line_name IS 'Line name.';
COMMENT ON COLUMN production_lines.product_family IS 'Product family the line makes.';
